('seed-high-16-q15','seed-high-16',15,'single_choice','Ý chính phù hợp nhất với câu sau là gì? “团队合作的关键之一是让责任和预期保持清晰。”','Câu gốc: 团队合作的关键之一是让责任和预期保持清晰。 Nghĩa phù hợp: Một chìa khóa của hợp tác nhóm là giữ trách nhiệm và kỳ vọng rõ ràng. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
('seed-high-16-q16','seed-high-16',16,'single_choice','Ý chính phù hợp nhất với câu sau là gì? “在复杂任务中，明确目标有助于提高整体效率。”','Câu gốc: 在复杂任务中，明确目标有助于提高整体效率。 Nghĩa phù hợp: Trong nhiệm vụ phức tạp, xác định rõ mục tiêu giúp nâng cao hiệu quả tổng thể. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
('seed-high-16-q17','seed-high-16',17,'single_choice','Ý chính phù hợp nhất với câu sau là gì? “有效沟通不仅需要表达，也需要认真倾听。”','Câu gốc: 有效沟通不仅需要表达，也需要认真倾听。 Nghĩa phù hợp: Giao tiếp hiệu quả không chỉ cần diễn đạt mà còn cần lắng nghe nghiêm túc. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
('seed-high-16-q18','seed-high-16',18,'single_choice','Ý chính phù hợp nhất với câu sau là gì? “学习计划应根据实际情况不断调整。”','Câu gốc: 学习计划应根据实际情况不断调整。 Nghĩa phù hợp: Kế hoạch học tập nên được điều chỉnh liên tục theo tình hình thực tế. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
('seed-high-16-q19','seed-high-16',19,'single_choice','Ý chính phù hợp nhất với câu sau là gì? “面对变化时，保持灵活性往往比机械执行更重要。”','Câu gốc: 面对变化时，保持灵活性往往比机械执行更重要。 Nghĩa phù hợp: Khi đối mặt thay đổi, giữ sự linh hoạt thường quan trọng hơn thực hiện máy móc. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
('seed-high-16-q20','seed-high-16',20,'single_choice','Ý chính phù hợp nhất với câu sau là gì? “评价一个方案时，需要同时考虑成本、效果和可持续性。”','Câu gốc: 评价一个方案时，需要同时考虑成本、效果和可持续性。 Nghĩa phù hợp: Khi đánh giá một phương án, cần đồng thời xem xét chi phí, hiệu quả và tính bền vững. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
